-- OR: 120 researched stops.
--
-- 118 new, 2 updating a row already in the index.
-- After running this and scripts/refresh-site.mts, /explore should read
-- 7008.
--
-- Coordinates are deliberately NOT updated on conflict: a checked position
-- must never be replaced by an unchecked one. Where the existing row came
-- from the OpenStreetMap scan and is wrong by a kilometre, delete that slug
-- first and let this insert instead.
--
-- state is deliberately NOT updated either. That is how an overwritten stop
-- in another state keeps its old state and hides — so the collision check
-- above refuses rather than relying on anyone noticing afterwards.

insert into public.stops
  (name, slug, category, latitude, longitude, city, state, description,
   public_access, source, timezone)
values
  ('Astoria Column', 'astoria-column', 'roadside-oddities', 46.18133, -123.81756, 'Astoria', 'OR', 'Climb the 1926 hilltop column whose exterior spiral mural wraps Pacific Northwest history around a 125-foot concrete tower; the observation deck gives a commanding Columbia River view.', 'open', 'https://astoriacolumn.org/', 'America/Los_Angeles'),
  ('Peter Iredale Shipwreck', 'peter-iredale-shipwreck', 'weird-history', 46.17837, -123.98109, 'Hammond', 'OR', 'The rusting bow ribs of the four-masted Peter Iredale, driven ashore in 1906, remain embedded in the beach at Fort Stevens and are easiest to examine around lower tide.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=129', 'America/Los_Angeles'),
  ('Battery Russell', 'battery-russell', 'weird-history', 46.19256, -123.97539, 'Hammond', 'OR', 'Explore the concrete remains of a World War II-era coastal gun battery inside Fort Stevens, part of the harbor-defense complex attacked by a Japanese submarine in 1942.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=129', 'America/Los_Angeles'),
  ('Fort Stevens Historic Military Site', 'fort-stevens-historic-military-site', 'weird-history', 46.2012, -123.96243, 'Hammond', 'OR', 'The fort''s historic area preserves batteries, gun emplacements, interpretive displays and military structures from a coastal defense post that operated from the Civil War era through World War II.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=129', 'America/Los_Angeles'),
  ('Oregon Film Museum', 'oregon-film-museum', 'museums', 46.18854, -123.83549, 'Astoria', 'OR', 'Housed in the old Clatsop County Jail used in The Goonies, this small museum focuses on movies filmed in Oregon and lets visitors make short green-screen movie scenes.', 'open', 'https://www.oregonfilmmuseum.org/', 'America/Los_Angeles'),
  ('Flavel House Museum', 'flavel-house-museum', 'roadside-oddities', 46.18814, -123.83507, 'Astoria', 'OR', 'This ornate 1886 Queen Anne mansion preserves period rooms, elaborate woodwork and the lifestyle of river pilot Captain George Flavel''s family.', 'open', 'https://astoriamuseums.org/', 'America/Los_Angeles'),
  ('Columbia River Maritime Museum', 'columbia-river-maritime-museum', 'museums', 46.19022, -123.82322, 'Astoria', 'OR', 'A major maritime museum devoted to the famously dangerous Columbia River Bar, shipwrecks, navigation, Coast Guard rescues and the working river.', 'open', 'https://www.crmm.org/', 'America/Los_Angeles'),
  ('Lightship Columbia', 'lightship-columbia', 'weird-history', 46.19037, -123.82239, 'Astoria', 'OR', 'Board the retired Lightship Columbia at the maritime museum dock and see the floating lighthouse that once held station off the Columbia River entrance.', 'open', 'https://www.crmm.org/', 'America/Los_Angeles'),
  ('Astoria Underground Tour', 'astoria-underground-tour', 'weird-history', 46.1902, -123.82922, 'Astoria', 'OR', 'A guided tour enters a rehabilitated portion of Astoria''s old below-street tunnel system, pairing documented city history with local mystery and reconstructed underground rooms.', 'limited', 'https://traveloregon.com/plan-your-trip/guides-tours/tours-guided-trips/astoria-underground-tour/', 'America/Los_Angeles'),
  ('Garden of Surging Waves', 'garden-of-surging-waves', 'weird-history', 46.18813, -123.83138, 'Astoria', 'OR', 'This city park interprets Astoria''s Chinese immigrant history through symbolic stonework, sculpture and landscape design at a former civic plaza.', 'open', 'https://www.astoria.gov/Parks/Garden_of_Surging_Waves.aspx', 'America/Los_Angeles'),
  ('Fort Clatsop', 'fort-clatsop', 'weird-history', 46.13416, -123.879, 'Warrenton', 'OR', 'A reconstruction and archaeological landscape mark the winter encampment where the Lewis and Clark Expedition stayed from December 1805 to March 1806.', 'open', 'https://www.nps.gov/places/fort-clatsop-or.htm', 'America/Los_Angeles'),
  ('Lewis and Clark Salt Works', 'lewis-and-clark-salt-works', 'weird-history', 45.98438, -123.93192, 'Seaside', 'OR', 'A stone cairn marks the site where expedition members boiled seawater for weeks to make salt needed for the return trip east.', 'open', 'https://www.nps.gov/places/the-salt-works.htm', 'America/Los_Angeles'),
  ('Tillamook Rock Lighthouse Viewpoint', 'tillamook-rock-lighthouse-viewpoint', 'weird-history', 45.9423, -123.98787, 'Cannon Beach', 'OR', 'From Ecola State Park, look offshore toward isolated Tillamook Rock Lighthouse, the notoriously difficult 1881 light station nicknamed ''Terrible Tilly''; the island itself is not open to visitors.', 'roadside', 'https://traveloregon.com/things-to-do/culture-history/lighthouses/', 'America/Los_Angeles'),
  ('Camp 18 Logging Museum', 'camp-18-logging-museum', 'museums', 45.88565, -123.61399, 'Elsie', 'OR', 'An outdoor collection of giant steam donkeys, locomotives, logging equipment and timber-industry artifacts sits beside the highway at historic Camp 18.', 'open', 'https://www.camp18loggingmuseum.org/', 'America/Los_Angeles'),
  ('Bayocean Ghost Town Site', 'bayocean-ghost-town-site', 'weird-history', 45.51938, -123.94753, 'Tillamook', 'OR', 'Trails on the Bayocean Peninsula cross the former site of a resort community that lost streets, homes and landmarks to erosion before much of the town was abandoned.', 'open', 'https://www.oregonencyclopedia.org/articles/bayocean/', 'America/Los_Angeles'),
  ('Cape Meares Lighthouse', 'cape-meares-lighthouse', 'weird-history', 45.48647, -123.9783, 'Cape Meares', 'OR', 'Oregon''s shortest lighthouse tower stands on a dramatic headland and still holds its historic first-order Fresnel lens; interior access follows posted seasonal hours.', 'limited', 'https://stateparks.oregon.gov/?do=park.profile&parkId=131', 'America/Los_Angeles'),
  ('Octopus Tree', 'octopus-tree', 'roadside-oddities', 45.48434, -123.97274, 'Cape Meares', 'OR', 'This huge Sitka spruce splits into multiple upward-growing trunks instead of a conventional central crown, creating one of the coast''s strangest living landmarks.', 'open', 'https://stateparks.oregon.gov/?do=park.profile&parkId=131', 'America/Los_Angeles'),
  ('Neskowin Ghost Forest', 'neskowin-ghost-forest', 'roadside-oddities', 45.09773, -123.98917, 'Neskowin', 'OR', 'Ancient Sitka spruce stumps emerge from the surf and sand at low tide, remnants of a forest buried after a major coastal earthquake centuries ago.', 'limited', 'https://traveloregon.com/things-to-do/trip-ideas/favorite-trips/oregons-stranger-things/', 'America/Los_Angeles'),
  ('Devils Punchbowl — Otter Rock', 'devils-punchbowl-otter-rock', 'roadside-oddities', 44.74716, -124.06468, 'Otter Rock', 'OR', 'A collapsed sea cave forms a huge natural bowl where waves surge, swirl and explode against the rock walls during rougher tides.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=156', 'America/Los_Angeles'),
  ('Yaquina Head Lighthouse', 'yaquina-head-lighthouse', 'weird-history', 44.675, -124.07639, 'Newport', 'OR', 'Oregon''s tallest lighthouse rises above black basalt cliffs at Yaquina Head; restoration work and staffing can affect tower-tour availability, so check the current BLM notice before visiting.', 'limited', 'https://www.blm.gov/visit/yaquina-head-outstanding-natural-area', 'America/Los_Angeles'),
  ('Yaquina Bay Lighthouse', 'yaquina-bay-lighthouse', 'weird-history', 44.62416, -124.06302, 'Newport', 'OR', 'Built in 1871, this rare wooden lighthouse combines the keeper''s dwelling and light tower in one structure overlooking Yaquina Bay.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=148', 'America/Los_Angeles'),
  ('Ripley''s Believe It or Not! Newport', 'ripleys-believe-it-or-not-newport', 'museums', 44.63684, -124.05359, 'Newport', 'OR', 'The Newport Odditorium packs shrunken curiosities, optical illusions, unusual artifacts and interactive exhibits into a long-running Bayfront attraction.', 'open', 'https://www.ripleys.com/attractions/ripleys-believe-it-or-not-newport', 'America/Los_Angeles'),
  ('Hatfield Marine Science Center Visitor Center', 'hatfield-marine-science-center-visitor-center', 'museums', 44.6217, -124.04653, 'Newport', 'OR', 'Oregon State University''s public visitor center turns active marine research into exhibits on deep-sea life, coastal ecology, earthquakes and ocean science.', 'open', 'https://hmsc.oregonstate.edu/visitor-center', 'America/Los_Angeles'),
  ('Exploding Whale Memorial Park', 'exploding-whale-memorial-park', 'weird-history', 43.97038, -124.11644, 'Florence', 'OR', 'This riverside park''s name commemorates Florence''s infamous 1970 attempt to dispose of a beached sperm whale with dynamite, one of Oregon''s best-known bizarre news events.', 'open', 'https://www.ci.florence.or.us/parks/exploding-whale-memorial-park', 'America/Los_Angeles'),
  ('Darlingtonia State Natural Site', 'darlingtonia-state-natural-site', 'roadside-oddities', 44.04647, -124.09669, 'Florence', 'OR', 'A short boardwalk enters a bog filled with cobra lilies, carnivorous plants whose hooded leaves trap insects and give the site an almost alien appearance.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=81', 'America/Los_Angeles'),
  ('Sea Lion Caves', 'sea-lion-caves', 'roadside-oddities', 44.12177, -124.12695, 'Florence', 'OR', 'An elevator descends into a vast natural sea cave where wild Steller sea lions gather seasonally; viewing conditions vary with weather and animal movement.', 'open', 'https://www.sealioncaves.com/', 'America/Los_Angeles'),
  ('Heceta Head Lighthouse', 'heceta-head-lighthouse', 'weird-history', 44.13743, -124.12821, 'Florence', 'OR', 'The 1894 lighthouse sits high above the Pacific and still uses a first-order Fresnel lens; tower access is subject to staffing and weather.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkid=86', 'America/Los_Angeles'),
  ('Devils Churn', 'devils-churn', 'roadside-oddities', 44.28411, -124.11079, 'Yachats', 'OR', 'A narrow volcanic-rock inlet funnels incoming waves into a roaring churn, especially near high tide; stay on established viewpoints because sneaker waves can be deadly.', 'limited', 'https://www.fs.usda.gov/r06/siuslaw/recreation/cape-perpetua-scenic-area', 'America/Los_Angeles'),
  ('Thor''s Well', 'thors-well', 'roadside-oddities', 44.27843, -124.11351, 'Yachats', 'OR', 'This collapsed coastal sea cave appears to swallow and eject ocean water as waves move through it; the spectacle is best viewed from a safe distance around higher tide.', 'limited', 'https://www.fs.usda.gov/r06/siuslaw/recreation/cape-perpetua-scenic-area', 'America/Los_Angeles'),
  ('Spouting Horn at Cook''s Chasm', 'spouting-horn-at-cooks-chasm', 'roadside-oddities', 44.27729, -124.11248, 'Yachats', 'OR', 'Wave pressure forces seawater through a narrow opening in the lava shoreline, producing a natural geyser-like plume at favorable tides.', 'limited', 'https://www.fs.usda.gov/r06/siuslaw/recreation/cape-perpetua-scenic-area', 'America/Los_Angeles'),
  ('Cape Perpetua Stone Shelter', 'cape-perpetua-stone-shelter', 'roadside-oddities', 44.2874, -124.1103, 'Yachats', 'OR', 'A Civilian Conservation Corps stone shelter crowns Cape Perpetua, blending into the volcanic headland above one of the Oregon Coast''s highest road-accessible viewpoints.', 'open', 'https://www.fs.usda.gov/r06/siuslaw/recreation/cape-perpetua-scenic-area', 'America/Los_Angeles'),
  ('Oregon Dunes Overlook', 'oregon-dunes-overlook', 'roadside-oddities', 43.83318, -124.15163, 'Reedsport', 'OR', 'A developed overlook reveals part of the enormous coastal dune field that stretches for dozens of miles along the central Oregon coast.', 'open', 'https://www.fs.usda.gov/r06/siuslaw/recreation/oregon-dunes-national-recreation-area', 'America/Los_Angeles'),
  ('Face Rock State Scenic Viewpoint', 'face-rock-state-scenic-viewpoint', 'folklore', 43.10514, -124.43515, 'Bandon', 'OR', 'Offshore sea stacks form the profile called Face Rock, tied to a Coquille story about Princess Ewauna; viewpoints keep visitors on public, lawful access.', 'open', 'https://stateparks.oregon.gov/?do=park.profile&parkId=47', 'America/Los_Angeles'),
  ('Washed Ashore Bandon Gallery', 'washed-ashore-bandon-gallery', 'roadside-oddities', 43.11943, -124.41267, 'Bandon', 'OR', 'Giant sea-creature sculptures assembled from plastic debris collected on beaches turn marine trash into intentionally strange public art and conservation displays.', 'open', 'https://www.washedashore.org/visit/', 'America/Los_Angeles'),
  ('Coquille River Lighthouse', 'coquille-river-lighthouse', 'weird-history', 43.12381, -124.42408, 'Bandon', 'OR', 'The compact 1896 lighthouse stands at the mouth of the Coquille River inside Bullards Beach State Park; interior openings are seasonal.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=50', 'America/Los_Angeles'),
  ('Mary D. Hume Wreck', 'mary-d-hume-wreck', 'weird-history', 42.42434, -124.42015, 'Gold Beach', 'OR', 'The decaying hull of the 1881 steamer Mary D. Hume rests in the harbor, a visible remnant of the vessel''s long career in Pacific Coast service.', 'roadside', 'https://visitgoldbeach.com/year-round/suggested-itineraries/', 'America/Los_Angeles'),
  ('Prehistoric Gardens', 'prehistoric-gardens', 'roadside-oddities', 42.44674, -124.41076, 'Port Orford', 'OR', 'Twenty-three life-size dinosaur and prehistoric-reptile sculptures stand among giant ferns and old coastal forest along this family-run Highway 101 attraction.', 'open', 'https://www.prehistoricgardens.com/', 'America/Los_Angeles'),
  ('Cape Blanco Lighthouse', 'cape-blanco-lighthouse', 'weird-history', 42.83698, -124.56364, 'Port Orford', 'OR', 'Perched on Oregon''s westernmost headland, the 1870 lighthouse overlooks a remote stretch of coast; tours and access are seasonal and weather-dependent.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=44', 'America/Los_Angeles'),
  ('Port Orford Heads Lifeboat Station Museum', 'port-orford-heads-lifeboat-station-museum', 'weird-history', 42.74011, -124.51372, 'Port Orford', 'OR', 'The former Coast Guard lifeboat station preserves rescue-service artifacts and overlooks the dangerous waters where crews once launched from the cliffs.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=43', 'America/Los_Angeles'),
  ('Nobuo Fujita Bomb Site Trail', 'nobuo-fujita-bomb-site-trail', 'weird-history', 42.08082, -124.12105, 'Brookings', 'OR', 'A remote forest trail leads to an interpretive marker at the 1942 site where Japanese pilot Nobuo Fujita dropped incendiary bombs in the only enemy aircraft bombing of the contiguous U.S. during World War II; access requires rough unpaved roads.', 'limited', 'https://brookings.or.us/291/Fujita-Sword', 'America/Los_Angeles'),
  ('Paul Bunyan Statue — Portland', 'paul-bunyan-statue-portland', 'roadside-oddities', 45.58382, -122.6866, 'Portland', 'OR', 'A towering fiberglass Paul Bunyan has watched over Portland''s Kenton neighborhood since 1959, a classic remnant of mid-century roadside promotion.', 'roadside', 'https://www.portland.gov/parks/paul-bunyan-statue', 'America/Los_Angeles'),
  ('Freakybuttrue Peculiarium', 'freakybuttrue-peculiarium', 'museums', 45.5353, -122.69758, 'Portland', 'OR', 'A deliberately bizarre museum mixes cryptids, fake medical oddities, interactive art and sideshow-style displays into one of Portland''s most unabashedly strange stops.', 'open', 'https://peculiarium.com/', 'America/Los_Angeles'),
  ('Skeleton Key Odditorium', 'skeleton-key-odditorium', 'museums', 45.51824, -122.68343, 'Portland', 'OR', 'A compact oddities shop and museum combines taxidermy, natural-history curiosities, macabre objects and rotating displays.', 'open', 'https://www.skeletonkeyodditorium.com/odditorium', 'America/Los_Angeles'),
  ('Portland Shanghai Tunnels Tour', 'portland-shanghai-tunnels-tour', 'weird-history', 45.5253, -122.67378, 'Portland', 'OR', 'Guided tours enter accessible basement and tunnel spaces beneath Old Town while explaining the district''s documented history and separating some of the famous ''Shanghai tunnel'' stories from later legend.', 'limited', 'https://www.travelportland.com/culture/portland-shanghai-tunnels/', 'America/Los_Angeles'),
  ('Witch''s Castle', 'witchs-castle', 'weird-history', 45.52886, -122.72504, 'Portland', 'OR', 'This moss-covered stone ruin in Forest Park began as a Depression-era public restroom but acquired the far more memorable ''Witch''s Castle'' nickname and a layer of local folklore.', 'open', 'https://www.portland.gov/parks/forest-park', 'America/Los_Angeles'),
  ('Lone Fir Cemetery', 'lone-fir-cemetery', 'weird-history', 45.51816, -122.64236, 'Portland', 'OR', 'Portland''s oldest continuously used cemetery contains pioneer graves, Chinese American history and thousands of burials; visit respectfully during posted cemetery hours.', 'limited', 'https://www.oregonmetro.gov/places/lone-fir-cemetery', 'America/Los_Angeles'),
  ('Pittock Mansion', 'pittock-mansion', 'roadside-oddities', 45.5252, -122.71629, 'Portland', 'OR', 'The 1914 hilltop mansion is packed with period technology, elaborate rooms and city history; ghost stories about the Pittock family circulate as local lore rather than established fact.', 'open', 'https://pittockmansion.org/', 'America/Los_Angeles'),
  ('Oregon Rail Heritage Center', 'oregon-rail-heritage-center', 'museums', 45.50726, -122.66115, 'Portland', 'OR', 'See massive operating steam locomotives and restoration work inside the home of Portland''s historic locomotive collection.', 'open', 'https://orhf.org/visit-us/', 'America/Los_Angeles'),
  ('Mill Ends Park', 'mill-ends-park', 'roadside-oddities', 45.51628, -122.67338, 'Portland', 'OR', 'A tiny circle of soil in the middle of SW Naito Parkway became Portland''s famously miniature park after columnist Dick Fagan invented a whimsical leprechaun backstory for it.', 'open', 'https://www.portland.gov/parks/mill-ends-park', 'America/Los_Angeles'),
  ('Portlandia Statue', 'portlandia-statue', 'roadside-oddities', 45.51575, -122.67903, 'Portland', 'OR', 'The enormous hammered-copper Portlandia crouches above the Portland Building entrance, one of the largest hammered-copper statues in the United States.', 'roadside', 'https://www.portland.gov/fleet-and-facilities/facilities/portland-building', 'America/Los_Angeles'),
  ('Weather Machine', 'weather-machine', 'roadside-oddities', 45.51361, -122.68167, 'Portland', 'OR', 'At noon, a mechanical weather sculpture in Pioneer Courthouse Square reveals a symbol forecasting sun, rain or clouds while fanfare plays.', 'roadside', 'https://www.travelportland.com/attractions/pioneer-courthouse-square/', 'America/Los_Angeles'),
  ('Stark''s Vacuum Museum', 'starks-vacuum-museum', 'museums', 45.52321, -122.66098, 'Portland', 'OR', 'A working vacuum store displays historic cleaners and a timeline of domestic vacuum technology, including machines dating back to the industry''s early years.', 'open', 'https://starks.com/about/vacuum-museum/', 'America/Los_Angeles'),
  ('Zymoglyphic Museum', 'zymoglyphic-museum', 'museums', 45.51785, -122.59973, 'Portland', 'OR', 'This small artist-run museum presents invented natural history, faux scientific specimens and elaborate assemblages from the imaginary ''Zymoglyphic'' world; hours are limited.', 'limited', 'https://zymoglyphic.org/', 'America/Los_Angeles'),
  ('Movie Madness Museum', 'movie-madness-museum', 'museums', 45.51648, -122.61799, 'Portland', 'OR', 'Inside Portland''s giant video store, a museum displays screen-used costumes and props among a collection of more than 90,000 rental titles.', 'open', 'https://www.moviemadness.org/museum/', 'America/Los_Angeles'),
  ('The Grotto Cave', 'the-grotto-cave', 'roadside-oddities', 45.55327, -122.57321, 'Portland', 'OR', 'A Catholic shrine is built into a cliffside cave roughly 30 feet wide and nearly 50 feet high, with a marble Pietà set inside the rock.', 'open', 'https://thegrotto.org/visit/gardens/the-grotto/', 'America/Los_Angeles'),
  ('Mount Tabor Volcanic Cinder Cone', 'mount-tabor-volcanic-cinder-cone', 'roadside-oddities', 45.51151, -122.59398, 'Portland', 'OR', 'One of Portland''s signature city parks occupies an extinct volcanic cinder cone, making it an unusual urban place to walk across visible volcanic terrain.', 'open', 'https://www.portland.gov/parks/mt-tabor-park', 'America/Los_Angeles'),
  ('Rimsky-Korsakoffee House', 'rimsky-korsakoffee-house', 'roadside-oddities', 45.51778, -122.654, 'Portland', 'OR', 'A late-night dessert house hidden in an old Victorian is known for its eccentric classical-music theme, decorated rooms and deliberately theatrical atmosphere.', 'open', 'https://rimskykorsakoffeehouse.com/', 'America/Los_Angeles'),
  ('North American Bigfoot Center', 'north-american-bigfoot-center', 'cryptids', 45.43174, -122.34038, 'Boring', 'OR', 'Cliff Barackman''s museum presents Bigfoot casts, research material, alleged evidence and Sasquatch pop culture while treating the subject as an open investigation.', 'open', 'https://northamericanbigfootcenter.com/', 'America/Los_Angeles'),
  ('Oregon City Municipal Elevator', 'oregon-city-municipal-elevator', 'roadside-oddities', 45.35692, -122.60769, 'Oregon City', 'OR', 'A municipal elevator carries pedestrians between two levels of Oregon City inside a distinctive mid-century tower, functioning like a vertical public street.', 'open', 'https://www.orcity.org/1235/Municipal-Elevator', 'America/Los_Angeles'),
  ('End of the Oregon Trail Interpretive Center', 'end-of-the-oregon-trail-interpretive-center', 'weird-history', 45.36429, -122.59486, 'Oregon City', 'OR', 'Giant wagon-frame architecture marks the official end-of-trail interpretive complex, where exhibits cover overland migration and its effects on Indigenous communities.', 'open', 'https://www.nps.gov/places/000/end-of-the-oregon-trail-interpretive-center.htm', 'America/Los_Angeles'),
  ('McLoughlin House', 'mcloughlin-house', 'weird-history', 45.35756, -122.60559, 'Oregon City', 'OR', 'The preserved home of Hudson''s Bay Company figure John McLoughlin interprets early Oregon City, fur-trade power and settlement-era history.', 'open', 'https://www.nps.gov/fova/learn/historyculture/mcloughlin-house.htm', 'America/Los_Angeles'),
  ('Rice Northwest Museum of Rocks and Minerals', 'rice-northwest-museum-of-rocks-and-minerals', 'museums', 45.57426, -122.94836, 'Hillsboro', 'OR', 'A former ranch house holds meteorites, petrified wood, fluorescent minerals, crystals and one of the Pacific Northwest''s strongest public geology collections.', 'open', 'https://www.ricenorthwestmuseum.org/', 'America/Los_Angeles'),
  ('Evergreen Aviation & Space Museum', 'evergreen-aviation-space-museum', 'museums', 45.20386, -123.14294, 'McMinnville', 'OR', 'The enormous Hughes H-4 Hercules ''Spruce Goose'' dominates a museum filled with aircraft, spacecraft and Cold War-era technology.', 'open', 'https://www.evergreenmuseum.org/', 'America/Los_Angeles'),
  ('Wings & Waves Waterpark 747', 'wings-waves-waterpark-747', 'roadside-oddities', 45.20433, -123.14963, 'McMinnville', 'OR', 'A real Boeing 747 sits on the roof of a waterpark, with enclosed waterslides beginning inside the aircraft and spiraling down into the building.', 'open', 'https://www.wingsandwaveswaterpark.com/', 'America/Los_Angeles'),
  ('Bobbie the Wonder Dog Memorial', 'bobbie-the-wonder-dog-memorial', 'folklore', 45.00453, -122.78276, 'Silverton', 'OR', 'A memorial honors Bobbie, the dog celebrated for returning to Silverton in 1924 after becoming separated from his family in Indiana and traveling thousands of miles west.', 'roadside', 'https://silverton.or.us/', 'America/Los_Angeles'),
  ('Enchanted Forest', 'enchanted-forest', 'roadside-oddities', 44.83197, -123.00888, 'Turner', 'OR', 'A handmade theme park created by Roger Tofte winds through storybook buildings, tunnels, castles and sculpted fantasy scenes tucked into a wooded hillside.', 'limited', 'https://www.enchantedforest.com/', 'America/Los_Angeles'),
  ('Oregon State Hospital Museum of Mental Health', 'oregon-state-hospital-museum-of-mental-health', 'weird-history', 44.93825, -123.00427, 'Salem', 'OR', 'The museum interprets the history of Oregon''s state psychiatric hospital through patient stories, medical objects and changing approaches to mental-health treatment.', 'open', 'https://oshmuseum.org/visit/', 'America/Los_Angeles'),
  ('Oregon State Hospital Memorial', 'oregon-state-hospital-memorial', 'weird-history', 44.93906, -123.00758, 'Salem', 'OR', 'A memorial garden and columbarium honor thousands of former hospital patients whose cremated remains were stored for decades in copper canisters; visit quietly and respectfully.', 'limited', 'https://www.oregon.gov/oha/osh/pages/memorial.aspx', 'America/Los_Angeles'),
  ('Eco-Earth Globe', 'eco-earth-globe', 'roadside-oddities', 44.93881, -123.04403, 'Salem', 'OR', 'A giant former industrial acid-storage tank was transformed into a colorful relief globe covered with continents, animals and landmarks in Riverfront Park.', 'open', 'https://www.cityofsalem.net/government/shaping-salem-s-future/plans-projects/eco-earth-globe', 'America/Los_Angeles'),
  ('Historic Carousel & Museum of Albany', 'historic-carousel-museum-of-albany', 'museums', 44.6367, -123.10764, 'Albany', 'OR', 'Volunteers carve and paint an elaborate menagerie for a working hand-built carousel, with the carving studio and museum visible alongside the finished ride.', 'open', 'https://albanycarousel.com/plan-your-visit/', 'America/Los_Angeles'),
  ('The Last Blockbuster', 'the-last-blockbuster', 'roadside-oddities', 44.06722, -121.30361, 'Bend', 'OR', 'The Bend Blockbuster is the last remaining store in the once-global video-rental chain, still operating as a rental shop and nostalgia destination.', 'open', 'https://bendblockbuster.com/', 'America/Los_Angeles'),
  ('Petersen Rock Garden', 'petersen-rock-garden', 'roadside-oddities', 44.20312, -121.26222, 'Redmond', 'OR', 'A hand-built landscape of miniature castles, bridges, towers and monuments made from local rock spreads across a rural property begun in the 1930s.', 'open', 'https://www.petersenrockgarden.org/', 'America/Los_Angeles'),
  ('High Desert Museum', 'high-desert-museum', 'museums', 43.96592, -121.34153, 'Bend', 'OR', 'Indoor and outdoor exhibits combine wildlife, Indigenous history, logging, frontier life and high-desert ecology in a museum built around the region''s unusual landscape.', 'open', 'https://highdesertmuseum.org/', 'America/Los_Angeles'),
  ('Lava River Cave — Bend', 'lava-river-cave-bend', 'roadside-oddities', 43.89485, -121.36954, 'Bend', 'OR', 'A mile-long lava tube beneath Newberry''s volcanic landscape is open for self-guided walking during its seasonal operating period; timed-entry rules can apply.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/lava-river-cave', 'America/Los_Angeles'),
  ('Lava Butte', 'lava-butte', 'roadside-oddities', 43.91786, -121.35799, 'Bend', 'OR', 'A classic cinder cone rises beside Lava Lands, with a seasonal summit road and trail overlooking black lava flows created roughly 7,000 years ago.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/newberry-national-volcanic-monument', 'America/Los_Angeles'),
  ('Lava Cast Forest', 'lava-cast-forest', 'roadside-oddities', 43.80012, -121.29141, 'Bend', 'OR', 'Molten lava once flowed around living trees and hardened before the trunks burned away, leaving hollow tree molds preserved in the Newberry lava field.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/newberry-national-volcanic-monument', 'America/Los_Angeles'),
  ('Big Obsidian Flow', 'big-obsidian-flow', 'roadside-oddities', 43.69538, -121.2356, 'La Pine', 'OR', 'A trail crosses Oregon''s youngest major lava flow, a jagged expanse of black volcanic glass and pumice created during Newberry Volcano''s most recent eruptive episode.', 'limited', 'https://www.usgs.gov/volcanoes/newberry/science/big-obsidian-flow', 'America/Los_Angeles'),
  ('Fort Rock State Natural Area', 'fort-rock-state-natural-area', 'roadside-oddities', 43.3744, -121.07, 'Fort Rock', 'OR', 'A vast ring of volcanic tuff rises from the high desert like a ruined stone fortress, formed when magma erupted through an ancient lake.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=31', 'America/Los_Angeles'),
  ('Fort Rock Valley Historical Homestead Museum', 'fort-rock-valley-historical-homestead-museum', 'weird-history', 43.35534, -121.05857, 'Fort Rock', 'OR', 'Original homestead-era buildings relocated from the surrounding basin form a preserved frontier village of cabins, a church, school and other structures.', 'limited', 'https://fortrockoregon.com/', 'America/Los_Angeles'),
  ('Crack-in-the-Ground', 'crack-in-the-ground', 'roadside-oddities', 43.33281, -120.676, 'Christmas Valley', 'OR', 'A long volcanic fissure splits the high desert, allowing hikers to walk between steep rock walls; BLM warns that access roads are rugged and four-wheel drive is strongly recommended.', 'limited', 'https://www.blm.gov/visit/crack-ground', 'America/Los_Angeles'),
  ('Lost Forest Research Natural Area', 'lost-forest-research-natural-area', 'roadside-oddities', 43.35641, -120.37113, 'Christmas Valley', 'OR', 'An isolated stand of ponderosa pine survives miles from the region''s normal forest edge, protected within a remote BLM research natural area.', 'limited', 'https://www.blm.gov/visit/lost-forestdunesfossil-acec', 'America/Los_Angeles'),
  ('Christmas Valley Sand Dunes', 'christmas-valley-sand-dunes', 'roadside-oddities', 43.33466, -120.38952, 'Christmas Valley', 'OR', 'A large inland dune field rises unexpectedly from Oregon''s high desert beside Lost Forest; access is primitive and travelers should prepare for remote conditions.', 'limited', 'https://www.blm.gov/visit/lost-forestdunesfossil-acec', 'America/Los_Angeles'),
  ('Dee Wright Observatory', 'dee-wright-observatory', 'roadside-oddities', 44.26054, -121.80128, 'Sisters', 'OR', 'A lava-rock observatory built by the Civilian Conservation Corps sits in the middle of an immense black lava field, with viewing ports aimed at Cascade peaks.', 'limited', 'https://www.fs.usda.gov/r06/willamette/recreation/dee-wright-observatory', 'America/Los_Angeles'),
  ('Arnold Ice Cave', 'arnold-ice-cave', 'roadside-oddities', 43.90523, -121.15892, 'Bend', 'OR', 'A lava-tube cave east of Bend can retain ice well into warm weather; it is undeveloped, unlit and subject to rough-road and cave hazards.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/caves', 'America/Los_Angeles'),
  ('Pilot Butte', 'pilot-butte', 'roadside-oddities', 44.06055, -121.28326, 'Bend', 'OR', 'An extinct cinder cone rises directly inside Bend, with a summit viewpoint above the city; in September 2026 some trail work is temporarily affecting portions of the park.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=33', 'America/Los_Angeles'),
  ('Lava Lands Visitor Center', 'lava-lands-visitor-center', 'roadside-oddities', 43.90986, -121.35688, 'Bend', 'OR', 'The Newberry volcanic visitor center sits beside Lava Butte and black lava flows, serving as a hub for interpreting central Oregon''s recent volcanic history.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/newberry-national-volcanic-monument', 'America/Los_Angeles'),
  ('Paulina Peak', 'paulina-peak', 'roadside-oddities', 43.68918, -121.2548, 'La Pine', 'OR', 'The highest point on Newberry Volcano''s caldera rim provides a dramatic view into the crater, over Paulina and East lakes, and across central Oregon.', 'limited', 'https://www.fs.usda.gov/r06/deschutes/recreation/newberry-national-volcanic-monument', 'America/Los_Angeles'),
  ('Shaniko Ghost Town', 'shaniko-ghost-town', 'weird-history', 45.00374, -120.75227, 'Shaniko', 'OR', 'Once a major wool-shipping center, Shaniko survives as a tiny living ghost town with historic storefronts, a school, jail and hotel lining its unusually intact streets.', 'open', 'https://traveloregon.com/places-to-go/cities/shaniko/', 'America/Los_Angeles'),
  ('Sumpter Historic Mining Town', 'sumpter-historic-mining-town', 'weird-history', 44.74584, -118.20127, 'Sumpter', 'OR', 'This former gold-boom town retains historic buildings and mining remnants after fires and mining decline reduced a once-thriving community to a small mountain town.', 'open', 'https://traveloregon.com/things-to-do/culture-history/ghost-towns/secrets-oregons-ghost-towns/', 'America/Los_Angeles'),
  ('Sumpter Valley Dredge', 'sumpter-valley-dredge', 'roadside-oddities', 44.74254, -118.20417, 'Sumpter', 'OR', 'A giant preserved gold dredge sits in the valley it once tore through; current state-park notices should be checked because fire-response activity has temporarily affected visitor-center and trail access in 2026.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=174', 'America/Los_Angeles'),
  ('Sumpter Valley Railroad', 'sumpter-valley-railroad', 'weird-history', 44.74426, -118.20334, 'Sumpter', 'OR', 'Oregon''s surviving narrow-gauge heritage railroad runs excursion trains between McEwen and Sumpter, using historic equipment and steam when fire conditions permit.', 'limited', 'https://www.sumptervalleyrailroad.com/', 'America/Los_Angeles'),
  ('Granite Ghost Town', 'granite-ghost-town', 'weird-history', 44.80931, -118.41772, 'Granite', 'OR', 'A handful of residents and historic structures remain from a mining town that once held thousands; surrounding abandoned mines are hazardous and should never be entered.', 'limited', 'https://traveloregon.com/things-to-do/culture-history/ghost-towns/granite/', 'America/Los_Angeles'),
  ('Greenhorn Ghost Town', 'greenhorn-ghost-town', 'weird-history', 44.70915, -118.49724, 'Greenhorn', 'OR', 'This nearly empty incorporated mining town sits high in the Blue Mountains, where old roads, mining history and scattered private holdings require cautious, non-trespassing exploration.', 'limited', 'https://traveloregon.com/things-to-do/culture-history/ghost-towns/secrets-oregons-ghost-towns/', 'America/Los_Angeles'),
  ('Whitney Ghost Town', 'whitney-ghost-town', 'weird-history', 44.65955, -118.2905, 'Whitney', 'OR', 'Remnants of the former railroad and lumber settlement can still be seen near Oregon Route 7; structures and nearby land may be private, so observe only from lawful public areas.', 'roadside', 'https://traveloregon.com/things-to-do/culture-history/ghost-towns/secrets-oregons-ghost-towns/', 'America/Los_Angeles'),
  ('Cornucopia Ghost Town', 'cornucopia-ghost-town', 'weird-history', 45.00877, -117.19839, 'Cornucopia', 'OR', 'The former gold-mining settlement at the end of Cornucopia Highway retains scattered historic remnants amid private property; stay on public roads and respect all signs and gates.', 'roadside', 'https://www.oregonencyclopedia.org/articles/cornucopia/', 'America/Los_Angeles'),
  ('Kam Wah Chung State Heritage Site', 'kam-wah-chung-state-heritage-site', 'weird-history', 44.41867, -118.9569, 'John Day', 'OR', 'A remarkably preserved Chinese store, apothecary and community center contains thousands of artifacts left largely in place after its early-20th-century use.', 'limited', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=5', 'America/Los_Angeles'),
  ('Painted Hills', 'painted-hills', 'roadside-oddities', 44.64764, -120.26085, 'Mitchell', 'OR', 'Bands of red, gold, black and tan clay record changing ancient climates in one of the most visually surreal units of John Day Fossil Beds National Monument.', 'open', 'https://www.nps.gov/joda/planyourvisit/painted-hills-unit.htm', 'America/Los_Angeles'),
  ('Clarno Palisades', 'clarno-palisades', 'roadside-oddities', 44.91521, -120.47435, 'Fossil', 'OR', 'Towering fossil-bearing volcanic mudflow cliffs preserve evidence of a subtropical Oregon landscape that existed tens of millions of years ago.', 'open', 'https://www.nps.gov/joda/planyourvisit/clarno.htm', 'America/Los_Angeles'),
  ('Thomas Condon Paleontology Center', 'thomas-condon-paleontology-center', 'museums', 44.55299, -119.64615, 'Kimberly', 'OR', 'The fossil-beds visitor center displays prehistoric mammals and plants while windows into the working paleontology laboratory show how specimens are prepared and studied.', 'open', 'https://www.nps.gov/joda/planyourvisit/thomas-condon-paleontology-center.htm', 'America/Los_Angeles'),
  ('Geiser Grand Hotel', 'geiser-grand-hotel', 'roadside-oddities', 44.77689, -117.82938, 'Baker City', 'OR', 'A restored 1889 hotel preserves a soaring stained-glass atrium and elaborate Victorian interiors; stories of apparitions and unexplained activity are part of local hotel lore, not established fact.', 'open', 'https://www.geisergrand.com/', 'America/Los_Angeles'),
  ('Baker City Chinese Cemetery', 'baker-city-chinese-cemetery', 'weird-history', 44.78432, -117.81672, 'Baker City', 'OR', 'Interpretive signs at this small cemetery explain the Chinese community that helped shape Baker County; only one marked grave remains, and the site should be visited respectfully.', 'limited', 'https://traveloregon.com/things-to-do/culture-history/historic-sites-oregon-trail/chinese-cemetery/', 'America/Los_Angeles'),
  ('National Historic Oregon Trail Interpretive Center', 'national-historic-oregon-trail-interpretive-center', 'weird-history', 44.81461, -117.72884, 'Baker City', 'OR', 'A 500-acre BLM site combines immersive migration exhibits, wagon replicas, original Oregon Trail ruts and remnants of the Flagstaff gold mine.', 'open', 'https://www.blm.gov/learn/interpretive-centers/national-historic-oregon-trail-interpretive-center', 'America/Los_Angeles'),
  ('Pendleton Underground Tours', 'pendleton-underground-tours', 'weird-history', 45.67055, -118.78701, 'Pendleton', 'OR', 'Reservation-only tours descend beneath downtown sidewalks into former commercial spaces and passageways before visiting rooms tied to Pendleton''s vice-district history.', 'limited', 'https://pendletonundergroundtours.org/', 'America/Los_Angeles'),
  ('Tamástslikt Cultural Institute', 'tam-stslikt-cultural-institute', 'museums', 45.65423, -118.66311, 'Pendleton', 'OR', 'Operated by the Confederated Tribes of the Umatilla Indian Reservation, the museum presents Plateau history and culture from Cayuse, Umatilla and Walla Walla perspectives.', 'open', 'https://www.tamastslikt.org/', 'America/Los_Angeles'),
  ('The Lodge at Hot Lake Springs', 'the-lodge-at-hot-lake-springs', 'roadside-oddities', 45.24385, -117.95644, 'La Grande', 'OR', 'A restored brick resort beside naturally hot mineral springs occupies a site long associated with healing, railroad-era tourism and later ghost stories; paranormal claims are treated as folklore.', 'open', 'https://hotlakespringsresort.com/', 'America/Los_Angeles'),
  ('Pete French Round Barn', 'pete-french-round-barn', 'roadside-oddities', 43.13264, -118.64251, 'Diamond', 'OR', 'This enormous late-19th-century circular barn was built for rancher Pete French and used to train horses through winter; the site''s history also includes the land disputes that preceded French''s 1897 killing.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=209', 'America/Los_Angeles'),
  ('Diamond Craters Outstanding Natural Area', 'diamond-craters-outstanding-natural-area', 'roadside-oddities', 43.07762, -118.7501, 'Diamond', 'OR', 'A remote 17,000-acre volcanic field contains craters, vents, lava tubes, cinder cones, spatter cones and other basaltic features packed into one stark high-desert landscape.', 'limited', 'https://www.blm.gov/visit/diamond-craters-outstanding-natural-area', 'America/Los_Angeles'),
  ('Alvord Desert', 'alvord-desert', 'roadside-oddities', 42.50817, -118.53257, 'Fields', 'OR', 'A vast dry lakebed forms a nearly featureless playa beneath Steens Mountain; BLM warns never to drive onto wet or questionable surfaces because vehicles can become deeply stuck.', 'limited', 'https://www.blm.gov/visit/alvord-desert', 'America/Los_Angeles'),
  ('Favell Museum', 'favell-museum', 'museums', 42.21931, -121.79113, 'Klamath Falls', 'OR', 'A large private collection displays Native American artifacts, stone tools, beadwork, baskets and Western art; the museum itself notes more than 100,000 artifacts in its holdings.', 'open', 'https://favellmuseum.org/', 'America/Los_Angeles'),
  ('Baldwin Hotel Museum', 'baldwin-hotel-museum', 'weird-history', 42.22033, -121.78846, 'Klamath Falls', 'OR', 'A 1905 hotel preserved with dozens of furnished rooms offers a time-capsule look at early Klamath Falls; local ghost stories exist, but should be understood as folklore.', 'limited', 'https://museum.klamathcounty.org/496/Visit-the-Museum', 'America/Los_Angeles'),
  ('Collier Logging Museum', 'collier-logging-museum', 'museums', 42.64319, -121.88279, 'Chiloquin', 'OR', 'An extensive outdoor collection of historic logging machinery, railroad equipment and relocated pioneer structures documents the machinery that transformed Oregon''s forests.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=165', 'America/Los_Angeles'),
  ('Mitchell Monument and Japanese Balloon Bomb Site', 'mitchell-monument-and-japanese-balloon-bomb-site', 'weird-history', 42.43182, -120.86109, 'Bly', 'OR', 'A forest memorial marks the site where a Japanese balloon bomb killed Elsie Mitchell and five children in 1945, the only U.S. deaths from an enemy balloon bomb during World War II.', 'open', 'https://www.fs.usda.gov/', 'America/Los_Angeles'),
  ('Fort Klamath Museum', 'fort-klamath-museum', 'weird-history', 42.6913, -121.974, 'Fort Klamath', 'OR', 'The museum and parade grounds occupy part of the 1863 frontier fort site and interpret military, settler and regional history near the former post.', 'limited', 'https://museum.klamathcounty.org/427/Museums', 'America/Los_Angeles'),
  ('Oregon Caves National Monument', 'oregon-caves-national-monument', 'roadside-oddities', 42.10319, -123.40186, 'Cave Junction', 'OR', 'Guided tours enter marble caves carved by acidic groundwater; the cave is accessible only with a guide, and 2026 tours operate seasonally with reservations strongly recommended.', 'limited', 'https://www.nps.gov/orca/planyourvisit/hours.htm', 'America/Los_Angeles'),
  ('Bigfoot Trap', 'bigfoot-trap', 'cryptids', 42.0564, -123.13722, 'Jacksonville', 'OR', 'A heavy wooden box trap built in 1974 to catch an alleged Sasquatch still stands off the Collings Mountain Trail; it never caught Bigfoot and was later restored by the Forest Service.', 'limited', 'https://www.fs.usda.gov/media/162817', 'America/Los_Angeles'),
  ('Golden State Heritage Site', 'golden-state-heritage-site', 'weird-history', 42.68217, -123.33148, 'Wolf Creek', 'OR', 'Oregon State Parks preserves four buildings from the mining settlement of Golden, one of the state''s rare ghost towns protected specifically as a public heritage site.', 'open', 'https://stateparks.oregon.gov/index.cfm?do=park.profile&parkId=189', 'America/Los_Angeles'),
  ('Buncom Ghost Town', 'buncom-ghost-town', 'weird-history', 42.17401, -122.9981, 'Jacksonville', 'OR', 'Three preserved early-20th-century structures stand at a quiet Applegate Valley crossroads associated with an older mining settlement; view from lawful public access and respect surrounding private land.', 'roadside', 'https://www.oregonencyclopedia.org/articles/buncom/', 'America/Los_Angeles'),
  ('Grants Pass Caveman', 'grants-pass-caveman', 'roadside-oddities', 42.46196, -123.32299, 'Grants Pass', 'OR', 'A 22-foot fiberglass caveman installed in 1971 guards the city''s visitor center, an oversized survivor of the Oregon Cavemen promotional tradition.', 'roadside', 'https://www.grantspassoregon.gov/2092/Oregon-Caveman', 'America/Los_Angeles'),
  ('It''s a Burl', 'its-a-burl', 'roadside-oddities', 42.19966, -123.65091, 'Kerby', 'OR', 'A woodworking compound and gallery turns giant burls into furniture, carvings and eccentric outdoor structures, creating a roadside environment that feels part workshop and part folk-art maze.', 'open', 'https://itsaburl.com/', 'America/Los_Angeles'),
  ('Siskiyou Smokejumper Base Museum', 'siskiyou-smokejumper-base-museum', 'museums', 42.10379, -123.68147, 'Cave Junction', 'OR', 'One of America''s earliest smokejumper bases preserves buildings, aircraft history and equipment from the era when firefighters parachuted from here into remote wildfires.', 'limited', 'https://siskiyousmokejumpermuseum.org/', 'America/Los_Angeles')
